$ErrorActionPreference='Stop'
$root='data/gt/candidates/ocr-dialogue-expansion-v1'
function Save-New($p,$o){if(Test-Path -LiteralPath $p){throw "Existing evidence $p"};[IO.File]::WriteAllText([IO.Path]::GetFullPath($p),($o|ConvertTo-Json -Depth 35),[Text.UTF8Encoding]::new($false))}
$corrections=@{
 'intro-greeting'=@(@(6072,'はじめまして！','ポケット モンスターの せかいへ','C1A'),@(6095,'はじめまして！','ポケット モンスターの せかいへ','C1'),@(6116,'はじめまして！','ポケット モンスターの せかいへ','C1A'),@(6137,'はじめまして！','ポケット モンスターの せかいへ','C1'),@(6139,'はしめまして！','ポケット モンスターの せかいへ','S'),@(6142,'ポケット モンスターの せかいへ','',''))
 'intro-oak'=@(@(6179,'わたしの なまえは オーキド','み',''),@(6182,'わたしの なまえは オーキド','みんなからは',''),@(6187,'わたしの なまえは オーキド','みんなからは ポケモン はかせと','C1'),@(6188,'わたしの なまえは オーキド','みんなからは ポケモン はかせと','C1A'),@(6197,'わたしの なまえは オーキト','みんなからは ポケモン はかせと','S'),@(6199,'みんなからは ポケモン はかせと','',''),@(6208,'みんなからは ポケモン はかせと','したわれて おるよ','C2AF'),@(6211,'みんなからは ポケモン はかせと','したわれて おるよ','C2F'),@(6217,'','','empty_target'))
 'intro-creatures'=@(@(6293,'いきもの たちが','いたる',''),@(6318,'いきもの たちが','いたるところに すんでいる！','C2A'))
 'intro-pets'=@(@(6336,'その ポケモン という いき','',''),@(6344,'その ポケモン という いきものを','ひとは ペットに したり','C1'),@(6345,'その ポケモン という いきものを','ひとは ペットに したり','C1A'),@(6365,'その ホケモン という いきものを','ひとは ペットに したり','S'),@(6368,'ひとは ペットに したり','',''),@(6371,'ひとは ペットに したり','しょう',''),@(6372,'ひとは ペットに したり','しょうぶに',''),@(6374,'ひとは ペットに したり','しょうぶに つかっ',''))
 'intro-research'=@(@(6408,'そして・','',''),@(6429,'','','textbox_empty'),@(6466,'わたしは この ポケモンの','けんきゅうを してる というわけだ','C2AF'),@(6469,'わたしは この ポケモンの','けんきゅうを してる というわけだ','C2F'))
}
$remove=@{'intro-greeting'=@(6073,6138,6140);'intro-oak'=@(6180,6183,6200,6210,6218);'intro-creatures'=@(6292);'intro-pets'=@(6337,6364,6366,6370,6373);'intro-research'=@(6428,6468)}
foreach($id in @('intro-greeting','intro-oak','intro-creatures','intro-pets','intro-research')){
 $dir="$root/$id";$p1=Get-Content -Raw "$dir/manual-pass1.json"|ConvertFrom-Json
 $rows=@($p1.states|Where-Object{$_.startFrame -notin $remove[$id] -and $_.startFrame -notin @($corrections[$id]|ForEach-Object{$_[0]})})
 foreach($r in $corrections[$id]){$top=14;$bottom=16;if($r[3] -eq 'S'){$top=13;$bottom=15};$fields=@();if($r[1]){$fields+=@{id='message-top';role='dialogue';text=$r[1];col=1;row=$top}};if($r[2]){$fields+=@{id='message-bottom';role='dialogue';text=$r[2];col=1;row=$bottom}};$complete=$r[3].StartsWith('C');$s=@{startFrame=$r[0];kind=if($r[3] -eq 'S'){'scrolling'}elseif($complete -and $r[3].Contains('F')){'message_fading'}elseif($complete){'message_complete'}elseif($fields.Count){'message_loading'}else{$r[3]};fields=$fields;completePage=$complete;menuCursors=@()};if($complete){$s.pageOpportunityId=$id+'-'+$r[3].Substring(1,1)};if($r[3].Contains('A')){$s.downArrow=@{style='filled_down';gridRect=@(18,16,19,17)}};if($r[3] -eq 'S'){$s.renderNote='Direct second raw read confirms8-pixel upward base shift and clipped upper diacritics; never restore invisible marks'};$rows+=[pscustomobject]$s}
 $states=@($rows|Sort-Object startFrame)
 for($i=0;$i -lt $states.Count;$i++){$end=if($i+1 -lt $states.Count){$states[$i+1].startFrame}else{$p1.scoredRange[1]};$states[$i]|Add-Member -NotePropertyName endFrameExclusive -NotePropertyValue $end -Force}
 $manual=@{mediaId=$p1.mediaId;mediaSha256=$p1.mediaSha256;name=$p1.name;source='data/frames/video-01/dialogue-intro-pass2-v1';status='agent_second_raw_read_complete_not_frozen';range=$p1.range;scoredRange=$p1.scoredRange;states=$states;frozen=$false;humanPerFrameVerification='not claimed';secondRead='Fresh source-from-start re-decode6056-6482; all426 original frames viewed in ordered sheets000-010, raw scroll6137-6143 zoom and fade6215-6219 zoom; thresholded pixel scan navigation used to find missed boundaries, never generates text';notes=@('Second read corrects first snapshot timing and arrow omissions; original pass1 retained','Two passes refer to original frames and no tested OCR/production translation exists','Five natural spoken blocks,10 complete page opportunities; all source frames incl empty/loading/scroll/fade retained','Centred dots each occupy one canonical cell; U+30FB; not one-cell ellipsis. No future text filled into loading frames')}
 Save-New "$dir/manual-pass2.json" $manual
 $layout=@{schemaVersion=2;sourceFrameSize=@(800,480);sourceGameRect=@(240,96,560,384);canonicalGameSize=@(160,144);cellPixels=@(8,8);sourceOrigin=@(240,96);sourceScaleNumerator=2;sourceScaleDenominator=1;scope='Opening speech original2x raster; base rows14/16, scrolling13/15; all coordinates from original frame pixels'}
 Save-New "$dir/layout-v1.json" $layout
 Save-New "$dir/pass-differences-v1.json" @{first='manual-pass1.json';second='manual-pass2.json';status='agent_double_raw_read_differences_resolved_not_approved';corrections=$corrections[$id];replacedFirstBoundaries=$remove[$id];basis='Direct raw second frame read and adjacent-frame/arrow/pixel navigation; no tested output';unresolvedScoreDifferences=0;frozen=$false;humanPerFrameVerification='not claimed'}
 & ./tools/encode-visible-gt.ps1 -Notes "$dir/manual-pass2.json" -Layout "$dir/layout-v1.json" -Destination "$dir/ocr-candidate-v1.jsonl" -Status agent_double_read_complete_candidate
 if($LASTEXITCODE){throw 'Encoding failed'}
}
